insert into public.recipes (locale, title, description, ingredients, steps, prep_minutes, servings, tags)
values
  ('he', 'שקשוקה', 'ביצים ברוטב עגבניות חריף-עדין. ארוחת ערב קלאסית במחבת אחת.', '[{"name": "ביצים", "qty": "4"}, {"name": "עגבניות", "qty": "5"}, {"name": "בצל", "qty": "1"}, {"name": "שום", "qty": "2 שיניים"}, {"name": "פלפל אדום", "qty": "1"}, {"name": "רסק עגבניות", "qty": "2 כפות"}, {"name": "פפריקה", "qty": "1 כפית"}, {"name": "כמון", "qty": "1 כפית"}, {"name": "שמן זית", "qty": "2 כפות"}]'::jsonb, array['מטגנים בצל ופלפל קצוצים בשמן זית עד שמתרככים.', 'מוסיפים שום, פפריקה, כמון ורסק ומערבבים דקה.', 'מוסיפים עגבניות קצוצות ומבשלים 10 דקות עד שהרוטב מסמיך.', 'שוברים פנימה את הביצים, מכסים ומבשלים 5–7 דקות.', 'מגישים עם לחם טרי.']::text[], 25, 3, array['quick', 'vegetarian', 'builtin:shakshuka']::text[]),
  ('en', 'Shakshuka', 'Eggs poached in a gently spiced tomato sauce. A one-pan dinner classic.', '[{"name": "Eggs", "qty": "4"}, {"name": "Tomatoes", "qty": "5"}, {"name": "Onion", "qty": "1"}, {"name": "Garlic", "qty": "2 cloves"}, {"name": "Red pepper", "qty": "1"}, {"name": "Tomato paste", "qty": "2 tbsp"}, {"name": "Paprika", "qty": "1 tsp"}, {"name": "Cumin", "qty": "1 tsp"}, {"name": "Olive oil", "qty": "2 tbsp"}]'::jsonb, array['Fry the chopped onion and pepper in olive oil until soft.', 'Add garlic, paprika, cumin and tomato paste; stir for a minute.', 'Add chopped tomatoes and simmer 10 minutes until thick.', 'Crack in the eggs, cover and cook 5–7 minutes.', 'Serve with fresh bread.']::text[], 25, 3, array['quick', 'vegetarian', 'builtin:shakshuka']::text[]),
  ('ru', 'Шакшука', 'Яйца в пряном томатном соусе. Классический ужин в одной сковороде.', '[{"name": "Яйца", "qty": "4"}, {"name": "Помидоры", "qty": "5"}, {"name": "Лук", "qty": "1"}, {"name": "Чеснок", "qty": "2 зубчика"}, {"name": "Красный перец", "qty": "1"}, {"name": "Томатная паста", "qty": "2 ст. л."}, {"name": "Паприка", "qty": "1 ч. л."}, {"name": "Кумин", "qty": "1 ч. л."}, {"name": "Оливковое масло", "qty": "2 ст. л."}]'::jsonb, array['Обжарьте нарезанные лук и перец в оливковом масле до мягкости.', 'Добавьте чеснок, паприку, кумин и томатную пасту, перемешайте минуту.', 'Добавьте нарезанные помидоры и тушите 10 минут.', 'Разбейте яйца, накройте и готовьте 5–7 минут.', 'Подавайте со свежим хлебом.']::text[], 25, 3, array['quick', 'vegetarian', 'builtin:shakshuka']::text[]),
  ('he', 'פסטה ברוטב עגבניות', 'רוטב עגבניות ושום פשוט שמוכן בזמן שהפסטה מתבשלת.', '[{"name": "פסטה", "qty": "500 גרם"}, {"name": "רוטב עגבניות", "qty": "1 צנצנת"}, {"name": "שום", "qty": "3 שיניים"}, {"name": "בזיליקום", "qty": "חופן"}, {"name": "פרמזן", "qty": "50 גרם"}, {"name": "שמן זית", "qty": "2 כפות"}]'::jsonb, array['מבשלים את הפסטה במים רותחים ומומלחים.', 'במקביל מטגנים שום פרוס בשמן זית דקה אחת.', 'מוסיפים את רוטב העגבניות ומבשלים 10 דקות.', 'מערבבים את הפסטה ברוטב, ומגישים עם בזיליקום ופרמזן.']::text[], 20, 4, array['quick', 'vegetarian', 'builtin:tomato_pasta']::text[]),
  ('en', 'Tomato pasta', 'A simple garlic-tomato sauce, ready while the pasta cooks.', '[{"name": "Pasta", "qty": "500 g"}, {"name": "Tomato sauce", "qty": "1 jar"}, {"name": "Garlic", "qty": "3 cloves"}, {"name": "Basil", "qty": "a handful"}, {"name": "Parmesan", "qty": "50 g"}, {"name": "Olive oil", "qty": "2 tbsp"}]'::jsonb, array['Cook the pasta in salted boiling water.', 'Meanwhile fry sliced garlic in olive oil for a minute.', 'Add the tomato sauce and simmer 10 minutes.', 'Toss the pasta in the sauce and serve with basil and parmesan.']::text[], 20, 4, array['quick', 'vegetarian', 'builtin:tomato_pasta']::text[]),
  ('ru', 'Паста в томатном соусе', 'Простой томатный соус с чесноком, готов пока варится паста.', '[{"name": "Паста", "qty": "500 г"}, {"name": "Томатный соус", "qty": "1 банка"}, {"name": "Чеснок", "qty": "3 зубчика"}, {"name": "Базилик", "qty": "горсть"}, {"name": "Пармезан", "qty": "50 г"}, {"name": "Оливковое масло", "qty": "2 ст. л."}]'::jsonb, array['Сварите пасту в подсоленной воде.', 'Тем временем обжарьте чеснок в оливковом масле минуту.', 'Добавьте томатный соус и тушите 10 минут.', 'Смешайте пасту с соусом, подавайте с базиликом и пармезаном.']::text[], 20, 4, array['quick', 'vegetarian', 'builtin:tomato_pasta']::text[]),
  ('he', 'שניצל עוף', 'שניצל פריך מהמחבת, אהוב על כל הבית.', '[{"name": "חזה עוף", "qty": "600 גרם"}, {"name": "ביצים", "qty": "2"}, {"name": "פירורי לחם", "qty": "1 כוס"}, {"name": "קמח", "qty": "חצי כוס"}, {"name": "שמן לטיגון", "qty": "1 כוס"}, {"name": "לימון", "qty": "1"}]'::jsonb, array['פורסים את החזה לפרוסות דקות ומרדדים קלות.', 'טובלים כל פרוסה בקמח, אחר כך בביצה טרופה ואז בפירורי לחם.', 'מטגנים בשמן חם 3–4 דקות מכל צד עד שהשניצל זהוב.', 'מניחים על נייר סופג ומגישים עם לימון.']::text[], 35, 4, array['kids', 'builtin:schnitzel']::text[]),
  ('en', 'Chicken schnitzel', 'Crispy pan-fried schnitzel that the whole home loves.', '[{"name": "Chicken breast", "qty": "600 g"}, {"name": "Eggs", "qty": "2"}, {"name": "Breadcrumbs", "qty": "1 cup"}, {"name": "Flour", "qty": "1/2 cup"}, {"name": "Frying oil", "qty": "1 cup"}, {"name": "Lemon", "qty": "1"}]'::jsonb, array['Slice the breast thinly and pound lightly.', 'Dip each slice in flour, then beaten egg, then breadcrumbs.', 'Fry in hot oil 3–4 minutes per side until golden.', 'Drain on paper towel and serve with lemon.']::text[], 35, 4, array['kids', 'builtin:schnitzel']::text[]),
  ('ru', 'Куриный шницель', 'Хрустящий шницель со сковороды, который любят все.', '[{"name": "Куриное филе", "qty": "600 г"}, {"name": "Яйца", "qty": "2"}, {"name": "Панировочные сухари", "qty": "1 стакан"}, {"name": "Мука", "qty": "1/2 стакана"}, {"name": "Масло для жарки", "qty": "1 стакан"}, {"name": "Лимон", "qty": "1"}]'::jsonb, array['Нарежьте филе тонко и слегка отбейте.', 'Обваляйте каждый кусок в муке, затем в яйце и в сухарях.', 'Жарьте в горячем масле 3–4 минуты с каждой стороны.', 'Выложите на бумажное полотенце и подавайте с лимоном.']::text[], 35, 4, array['kids', 'builtin:schnitzel']::text[]),
  ('he', 'מג׳דרה', 'אורז ועדשים עם הרבה בצל מטוגן. זול, משביע ומנחם.', '[{"name": "אורז", "qty": "1 כוס"}, {"name": "עדשים חומות", "qty": "1 כוס"}, {"name": "בצל", "qty": "3"}, {"name": "שמן", "qty": "4 כפות"}, {"name": "כמון", "qty": "1 כפית"}, {"name": "מלח", "qty": "1 כפית"}]'::jsonb, array['מבשלים את העדשים במים 15 דקות ומסננים.', 'במקביל מטגנים בצל פרוס בשמן עד שהוא חום ומתוק.', 'מוסיפים לסיר את האורז, העדשים, הכמון והמלח ו־2 כוסות מים.', 'מבשלים מכוסה על אש נמוכה 20 דקות.', 'מגישים עם הבצל המטוגן מעל.']::text[], 50, 4, array['vegetarian', 'budget', 'builtin:majadra']::text[]),
  ('en', 'Majadra', 'Rice and lentils with lots of fried onion. Cheap, filling and comforting.', '[{"name": "Rice", "qty": "1 cup"}, {"name": "Brown lentils", "qty": "1 cup"}, {"name": "Onion", "qty": "3"}, {"name": "Oil", "qty": "4 tbsp"}, {"name": "Cumin", "qty": "1 tsp"}, {"name": "Salt", "qty": "1 tsp"}]'::jsonb, array['Boil the lentils for 15 minutes and drain.', 'Meanwhile fry sliced onion in oil until deep brown and sweet.', 'Put rice, lentils, cumin, salt and 2 cups of water in a pot.', 'Cook covered on low heat for 20 minutes.', 'Serve topped with the fried onion.']::text[], 50, 4, array['vegetarian', 'budget', 'builtin:majadra']::text[]),
  ('ru', 'Маджадра', 'Рис с чечевицей и жареным луком. Дёшево, сытно и уютно.', '[{"name": "Рис", "qty": "1 стакан"}, {"name": "Коричневая чечевица", "qty": "1 стакан"}, {"name": "Лук", "qty": "3"}, {"name": "Масло", "qty": "4 ст. л."}, {"name": "Кумин", "qty": "1 ч. л."}, {"name": "Соль", "qty": "1 ч. л."}]'::jsonb, array['Отварите чечевицу 15 минут и слейте воду.', 'Тем временем обжарьте лук до тёмно-золотистого цвета.', 'Положите в кастрюлю рис, чечевицу, кумин, соль и 2 стакана воды.', 'Варите под крышкой на слабом огне 20 минут.', 'Подавайте с жареным луком сверху.']::text[], 50, 4, array['vegetarian', 'budget', 'builtin:majadra']::text[]),
  ('he', 'סלט ישראלי', 'קצוץ דק, לימון ושמן זית. מתאים לכל ארוחה.', '[{"name": "עגבניות", "qty": "4"}, {"name": "מלפפונים", "qty": "4"}, {"name": "בצל סגול", "qty": "1"}, {"name": "פטרוזיליה", "qty": "חופן"}, {"name": "לימון", "qty": "1"}, {"name": "שמן זית", "qty": "2 כפות"}]'::jsonb, array['קוצצים עגבניות, מלפפונים ובצל לקוביות קטנות.', 'מוסיפים פטרוזיליה קצוצה.', 'מתבלים במיץ לימון, שמן זית ומלח, ומערבבים ממש לפני ההגשה.']::text[], 10, 4, array['quick', 'vegetarian', 'builtin:israeli_salad']::text[]),
  ('en', 'Israeli salad', 'Finely chopped, with lemon and olive oil. Goes with any meal.', '[{"name": "Tomatoes", "qty": "4"}, {"name": "Cucumbers", "qty": "4"}, {"name": "Red onion", "qty": "1"}, {"name": "Parsley", "qty": "a handful"}, {"name": "Lemon", "qty": "1"}, {"name": "Olive oil", "qty": "2 tbsp"}]'::jsonb, array['Dice tomatoes, cucumbers and onion small.', 'Add chopped parsley.', 'Dress with lemon juice, olive oil and salt just before serving.']::text[], 10, 4, array['quick', 'vegetarian', 'builtin:israeli_salad']::text[]),
  ('ru', 'Израильский салат', 'Мелко нарезанный, с лимоном и оливковым маслом.', '[{"name": "Помидоры", "qty": "4"}, {"name": "Огурцы", "qty": "4"}, {"name": "Красный лук", "qty": "1"}, {"name": "Петрушка", "qty": "пучок"}, {"name": "Лимон", "qty": "1"}, {"name": "Оливковое масло", "qty": "2 ст. л."}]'::jsonb, array['Нарежьте помидоры, огурцы и лук мелким кубиком.', 'Добавьте рубленую петрушку.', 'Заправьте лимонным соком, маслом и солью перед подачей.']::text[], 10, 4, array['quick', 'vegetarian', 'builtin:israeli_salad']::text[]),
  ('he', 'מרק עדשים כתומות', 'מרק סמיך ומחמם, נגמר בסיר אחד.', '[{"name": "עדשים כתומות", "qty": "1.5 כוסות"}, {"name": "גזר", "qty": "2"}, {"name": "בצל", "qty": "1"}, {"name": "שום", "qty": "2 שיניים"}, {"name": "כמון", "qty": "1 כפית"}, {"name": "כורכום", "qty": "חצי כפית"}, {"name": "לימון", "qty": "1"}]'::jsonb, array['מטגנים בצל, גזר ושום קצוצים 5 דקות.', 'מוסיפים כמון, כורכום, עדשים שטופות ו־6 כוסות מים.', 'מבשלים 25 דקות עד שהעדשים מתפרקות.', 'טוחנים במוט, מתקנים תיבול ומגישים עם לימון.']::text[], 40, 6, array['vegetarian', 'budget', 'builtin:lentil_soup']::text[]),
  ('en', 'Red lentil soup', 'A thick, warming soup made in one pot.', '[{"name": "Red lentils", "qty": "1.5 cups"}, {"name": "Carrots", "qty": "2"}, {"name": "Onion", "qty": "1"}, {"name": "Garlic", "qty": "2 cloves"}, {"name": "Cumin", "qty": "1 tsp"}, {"name": "Turmeric", "qty": "1/2 tsp"}, {"name": "Lemon", "qty": "1"}]'::jsonb, array['Fry chopped onion, carrot and garlic for 5 minutes.', 'Add cumin, turmeric, rinsed lentils and 6 cups of water.', 'Simmer 25 minutes until the lentils fall apart.', 'Blend, season and serve with lemon.']::text[], 40, 6, array['vegetarian', 'budget', 'builtin:lentil_soup']::text[]),
  ('ru', 'Суп из красной чечевицы', 'Густой согревающий суп в одной кастрюле.', '[{"name": "Красная чечевица", "qty": "1.5 стакана"}, {"name": "Морковь", "qty": "2"}, {"name": "Лук", "qty": "1"}, {"name": "Чеснок", "qty": "2 зубчика"}, {"name": "Кумин", "qty": "1 ч. л."}, {"name": "Куркума", "qty": "1/2 ч. л."}, {"name": "Лимон", "qty": "1"}]'::jsonb, array['Обжарьте лук, морковь и чеснок 5 минут.', 'Добавьте кумин, куркуму, чечевицу и 6 стаканов воды.', 'Варите 25 минут, пока чечевица не разварится.', 'Измельчите блендером, посолите и подавайте с лимоном.']::text[], 40, 6, array['vegetarian', 'budget', 'builtin:lentil_soup']::text[]),
  ('he', 'עוף בתנור עם תפוחי אדמה', 'הכל בתבנית אחת, והתנור עושה את העבודה.', '[{"name": "כרעיים", "qty": "6"}, {"name": "תפוחי אדמה", "qty": "1 ק״ג"}, {"name": "בצל", "qty": "2"}, {"name": "שום", "qty": "6 שיניים"}, {"name": "פפריקה", "qty": "2 כפיות"}, {"name": "שמן זית", "qty": "4 כפות"}]'::jsonb, array['מחממים תנור ל־200 מעלות.', 'חותכים תפוחי אדמה ובצל ומסדרים בתבנית עם שיני שום.', 'משפשפים את העוף בשמן, פפריקה ומלח ומניחים מעל.', 'אופים כשעה, עד שהעוף שחום ותפוחי האדמה רכים.']::text[], 70, 4, array['weekend', 'builtin:roast_chicken']::text[]),
  ('en', 'Roast chicken with potatoes', 'Everything in one tray; the oven does the work.', '[{"name": "Chicken legs", "qty": "6"}, {"name": "Potatoes", "qty": "1 kg"}, {"name": "Onion", "qty": "2"}, {"name": "Garlic", "qty": "6 cloves"}, {"name": "Paprika", "qty": "2 tsp"}, {"name": "Olive oil", "qty": "4 tbsp"}]'::jsonb, array['Heat the oven to 200°C.', 'Cut potatoes and onion and spread in a tray with the garlic.', 'Rub the chicken with oil, paprika and salt and place on top.', 'Roast about an hour until browned and the potatoes are soft.']::text[], 70, 4, array['weekend', 'builtin:roast_chicken']::text[]),
  ('ru', 'Курица с картошкой в духовке', 'Всё в одном противне — работу делает духовка.', '[{"name": "Куриные окорочка", "qty": "6"}, {"name": "Картофель", "qty": "1 кг"}, {"name": "Лук", "qty": "2"}, {"name": "Чеснок", "qty": "6 зубчиков"}, {"name": "Паприка", "qty": "2 ч. л."}, {"name": "Оливковое масло", "qty": "4 ст. л."}]'::jsonb, array['Разогрейте духовку до 200°C.', 'Нарежьте картофель и лук, выложите в противень с чесноком.', 'Натрите курицу маслом, паприкой и солью, положите сверху.', 'Запекайте около часа до румяной корочки.']::text[], 70, 4, array['weekend', 'builtin:roast_chicken']::text[]),
  ('he', 'מוקפץ אטריות וירקות', 'ירקות צבעוניים ואטריות ברוטב סויה, מהיר וטעים.', '[{"name": "אטריות", "qty": "400 גרם"}, {"name": "פלפל", "qty": "2"}, {"name": "גזר", "qty": "2"}, {"name": "ברוקולי", "qty": "1"}, {"name": "רוטב סויה", "qty": "4 כפות"}, {"name": "שום", "qty": "2 שיניים"}, {"name": "ג׳ינג׳ר", "qty": "חתיכה קטנה"}]'::jsonb, array['מבשלים את האטריות לפי ההוראות ומסננים.', 'מקפיצים במחבת חמה שום, ג׳ינג׳ר וירקות חתוכים 5 דקות.', 'מוסיפים את האטריות ורוטב הסויה ומערבבים עוד 2 דקות.']::text[], 25, 4, array['quick', 'builtin:stir_fry']::text[]),
  ('en', 'Veggie noodle stir-fry', 'Colourful vegetables and noodles in soy sauce, quick and tasty.', '[{"name": "Noodles", "qty": "400 g"}, {"name": "Peppers", "qty": "2"}, {"name": "Carrots", "qty": "2"}, {"name": "Broccoli", "qty": "1"}, {"name": "Soy sauce", "qty": "4 tbsp"}, {"name": "Garlic", "qty": "2 cloves"}, {"name": "Ginger", "qty": "a small piece"}]'::jsonb, array['Cook the noodles as directed and drain.', 'Stir-fry garlic, ginger and sliced vegetables in a hot pan for 5 minutes.', 'Add noodles and soy sauce and toss for 2 more minutes.']::text[], 25, 4, array['quick', 'builtin:stir_fry']::text[]),
  ('ru', 'Лапша с овощами вок', 'Яркие овощи и лапша в соевом соусе — быстро и вкусно.', '[{"name": "Лапша", "qty": "400 г"}, {"name": "Перец", "qty": "2"}, {"name": "Морковь", "qty": "2"}, {"name": "Брокколи", "qty": "1"}, {"name": "Соевый соус", "qty": "4 ст. л."}, {"name": "Чеснок", "qty": "2 зубчика"}, {"name": "Имбирь", "qty": "небольшой кусочек"}]'::jsonb, array['Отварите лапшу по инструкции.', 'Обжарьте на сильном огне чеснок, имбирь и овощи 5 минут.', 'Добавьте лапшу и соевый соус, перемешайте ещё 2 минуты.']::text[], 25, 4, array['quick', 'builtin:stir_fry']::text[]),
  ('he', 'חביתת ירק', 'ארוחת בוקר או ערב בחמש דקות.', '[{"name": "ביצים", "qty": "3"}, {"name": "בצל ירוק", "qty": "2 גבעולים"}, {"name": "עגבנייה", "qty": "1"}, {"name": "גבינה צהובה", "qty": "2 פרוסות"}]'::jsonb, array['טורפים ביצים עם מלח ופלפל ובצל ירוק קצוץ.', 'יוצקים למחבת משומנת ומבשלים על אש בינונית.', 'מוסיפים עגבנייה וגבינה, מקפלים ומגישים.']::text[], 10, 1, array['quick', 'vegetarian', 'builtin:omelet']::text[]),
  ('en', 'Herb omelet', 'Breakfast or dinner in five minutes.', '[{"name": "Eggs", "qty": "3"}, {"name": "Spring onion", "qty": "2 stalks"}, {"name": "Tomato", "qty": "1"}, {"name": "Yellow cheese", "qty": "2 slices"}]'::jsonb, array['Beat the eggs with salt, pepper and chopped spring onion.', 'Pour into an oiled pan and cook on medium heat.', 'Add tomato and cheese, fold and serve.']::text[], 10, 1, array['quick', 'vegetarian', 'builtin:omelet']::text[]),
  ('ru', 'Омлет с зеленью', 'Завтрак или ужин за пять минут.', '[{"name": "Яйца", "qty": "3"}, {"name": "Зелёный лук", "qty": "2 пера"}, {"name": "Помидор", "qty": "1"}, {"name": "Сыр", "qty": "2 ломтика"}]'::jsonb, array['Взбейте яйца с солью, перцем и зелёным луком.', 'Вылейте на смазанную сковороду, готовьте на среднем огне.', 'Добавьте помидор и сыр, сложите и подавайте.']::text[], 10, 1, array['quick', 'vegetarian', 'builtin:omelet']::text[]),
